<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreOrderRequest; use App\Models\Coupon; use App\Models\DeliveryZone; use App\Models\Order; use Illuminate\Support\Facades\DB; use Inertia\Inertia; use App\Services\OrderNotificationService;
class CheckoutController extends Controller {
 public function create(){ $cart=array_values(session('cart',[])); abort_if(!$cart,302,'/cart'); return Inertia::render('Checkout',['cart'=>$cart,'zones'=>DeliveryZone::where('is_active',true)->orderBy('name')->get(),'settings'=>['free_delivery_threshold'=>(float)\App\Models\Setting::getValue('free_delivery_threshold',500)]]); }
 public function store(StoreOrderRequest $request){ $cart=session('cart',[]); abort_if(!$cart,422,'Your cart is empty.'); $subtotal=(float)array_sum(array_column($cart,'subtotal')); $zone=DeliveryZone::findOrFail($request->delivery_zone_id); $free=(float)\App\Models\Setting::getValue('free_delivery_threshold',500); $delivery=$subtotal >= $free ? 0 : (float)$zone->fee; $coupon=null; $discount=0; if($request->filled('coupon_code')){$coupon=Coupon::where('code',strtoupper(trim($request->coupon_code)))->first(); if($coupon && $coupon->validFor($subtotal)) { $discount=$coupon->discount($subtotal); } else { return back()->withErrors(['coupon_code'=>'Invalid or expired coupon code.'])->withInput(); }} $total=max(0,$subtotal+$delivery-$discount);
  $order=DB::transaction(function()use($request,$cart,$subtotal,$delivery,$discount,$coupon,$total){$o=Order::create(['order_number'=>'DD'.now()->format('ymdHis').random_int(10,99),'customer_name'=>$request->customer_name,'phone'=>$request->phone,'area'=>$request->area,'address'=>$request->address,'apartment'=>$request->apartment,'notes'=>$request->notes,'subtotal'=>$subtotal,'delivery_fee'=>$delivery,'discount'=>$discount,'coupon_code'=>$coupon?->code,'total'=>$total,'payment_method'=>'cod','status'=>'pending']); foreach($cart as $line)$o->items()->create(['box_id'=>$line['box_id'],'box_size'=>$line['box_size'],'quantity'=>$line['quantity'],'unit_price'=>$line['unit_price'],'subtotal'=>$line['subtotal'],'selection'=>$line['selection']]); return $o;}); session()->forget('cart'); app(OrderNotificationService::class)->sendEmail($order);  return redirect()->route('order.success',$order); }
 public function success(Order $order){return Inertia::render('OrderSuccess',['order'=>$order->load('items')]);}
 public function track(string $orderNumber){$order=Order::where('order_number',$orderNumber)->firstOrFail(); return Inertia::render('TrackOrder',['order'=>$order->load('items')]);}
}
